function test_iterateConstParts(frmExpr, expr, parenCnt) {
  let constPartsToArr = constParts => constParts.begins.map((b, i) => [
    b,
    constParts.ends[i]
  ]);
  let frmConstParts = createConstParts(frmExpr);
  let constParts = createMatchingConstParts(frmConstParts);
  let matchingConstParts = [];
  iterateConstParts(frmExpr, expr, frmConstParts, constParts, 0, parenCnt, constParts => {
    matchingConstParts.push(constPartsToArr(constParts));
    return "Continue";
  });
  return [
    constPartsToArr(frmConstParts),
    matchingConstParts
  ];
}

function test_iterateSubstitutions(frmExpr, expr, parenCnt) {
  let frmConstParts = createConstParts(frmExpr);
  let constParts = createMatchingConstParts(frmConstParts);
  let varGroups = createVarGroups(frmExpr, frmConstParts);
  let numOfVars = Belt_SetInt.size(Belt_SetInt.fromArray(frmExpr.filter(i => i >= 0)));
  let subs = createSubs(numOfVars);
  let result = [];
  iterateSubstitutions(frmExpr, expr, frmConstParts, constParts, varGroups, subs, parenCnt, subs => {
    let res = [];
    for (let i = 0; i < numOfVars; ++i) {
      res.push(subs.exprs[i].slice(subs.begins[i], subs.ends[i] + 1 | 0));
    }
    result.push(res);
    return "Continue";
  });
  return result;
}

